func:
if (global.get('SYSTEM_SHUTDOWN')) {
    node.status({fill:'red',shape:'ring',text:'SHUTDOWN'});
    return null;
}
const gasUrl = global.get('GAS_URL') || env.get('GAS_WEBHOOK_URL') || '';
if (!gasUrl) {
    node.error('GAS_URL not configured');
    node.status({fill:'red',shape:'dot',text:'No GAS_URL'});
    return null;
}
const ts = new Date().toISOString();
msg._lq = { startedAt: ts, gasUrl: gasUrl.split('?')[0] };
msg.url = msg._lq.gasUrl + '?action=scoreAndSyncQualifiedRows';
msg.headers = { 'Content-Type': 'application/json' };
const apiKey = global.get('GAS_API_KEY') || env.get('GAS_API_KEY') || '';
if (apiKey) {
    msg.headers['X-API-Key'] = apiKey;
    msg.headers['X-Api-Key'] = apiKey;
}
msg.payload = {
    apiKey: apiKey,
    action: 'scoreAndSyncQualifiedRows',
    source: 'node-red-lead-qualification',
    requestedAt: ts
};
msg.method = 'POST';
global.set('last_run_scoreAndSyncQualifiedRows', ts);
node.status({fill:'blue',shape:'dot',text:'Scoring leads…'});
return msg;

msg._lq = msg._lq || {};
msg._lq.scoreResult = msg.payload;
const gasUrl = (msg._lq.gasUrl) || (global.get('GAS_URL') || '').split('?')[0];
msg.url = gasUrl + '?action=processConciergeQueue';
msg.headers = { 'Content-Type': 'application/json' };
const apiKey = global.get('GAS_API_KEY') || env.get('GAS_API_KEY') || '';
if (apiKey) {
    msg.headers['X-API-Key'] = apiKey;
    msg.headers['X-Api-Key'] = apiKey;
}
msg.payload = {
    apiKey: apiKey,
    action: 'processConciergeQueue',
    source: 'node-red-lead-qualification',
    requestedAt: new Date().toISOString()
};
msg.method = 'POST';
node.status({fill:'blue',shape:'dot',text:'Concierge queue…'});
return msg;

msg._lq = msg._lq || {};
msg._lq.conciergeResult = msg.payload;
const base = (global.get('LEADS_URL') || env.get('LEADS_PUBLIC_URL') || env.get('DASHBOARD_PUBLIC_URL') || 'https://leads.shamrockbailbonds.biz').replace(/\/$/, '');
msg.url = base + '/api/automation/lead-qualification';
const apiKey = global.get('GAS_API_KEY') || env.get('GAS_API_KEY') || '';
msg.headers = {
    'Content-Type': 'application/json',
    'X-API-Key': apiKey,
    'X-Api-Key': apiKey
};
msg.payload = {
    hours_back: 24,
    hot_threshold: 70,
    warm_threshold: 40,
    high_value_bond: 2500,
    limit: 40
};
msg.method = 'POST';
node.status({fill:'blue',shape:'dot',text:'Leads qualification…'});
return msg;

const data = msg.payload || {};
const c = data.counts || {};
const hot = data.hot || [];
const hv = data.high_value || [];
let lines = hot.slice(0, 5).map(h =>
    `• *${h.name || 'Unknown'}* (${h.county || '?'}) score=${h.lead_score} bond=$${(h.bond_amount||0).toLocaleString()}`
).join('\n');
if (!lines) lines = '_No hot leads in window_';
const hvLines = hv.slice(0, 3).map(h =>
    `• ${h.name || '?'} $${(h.bond_amount||0).toLocaleString()} — ${h.county || ''}`
).join('\n') || '_None_';

const text = [
    '🎯 *Lead Qualification Engine*',
    `Scanned: ${c.scanned || 0} · 🔥 Hot: ${c.hot || 0} · Warm: ${c.warm || 0} · HV: ${c.high_value || 0}`,
    '',
    '*Top Hot*',
    lines,
    '',
    '*High-Value Unposted (>$2.5k)*',
    hvLines
].join('\n');

msg.headers = {
    Authorization: 'Bearer ' + (global.get('SLACK_TOKEN') || global.get('SLACK_BOT_TOKEN') || env.get('SLACK_BOT_TOKEN') || ''),
    'Content-Type': 'application/json; charset=utf-8'
};
msg.payload = {
    channel: global.get('SLACK_CHANNEL_LEADS') || '#leads',
    text: text
};
// Only spam Slack when there is work
if ((c.hot || 0) === 0 && (c.high_value || 0) === 0) {
    node.status({fill:'green',shape:'ring',text:'Quiet — no hot/HV'});
    msg._skipSlack = true;
    return [null, msg];
}
node.status({fill:'green',shape:'dot',text:`Hot ${c.hot||0} · HV ${c.high_value||0}`});
return [msg, null];

const err = msg.error || {};
msg.headers = {
    Authorization: 'Bearer ' + (global.get('SLACK_TOKEN') || env.get('SLACK_BOT_TOKEN') || ''),
    'Content-Type': 'application/json; charset=utf-8'
};
msg.payload = {
    channel: '#alerts',
    text: '🚨 *Lead Qualification Engine error*: ' + (err.message || JSON.stringify(err).slice(0, 300))
};
return msg;

if (global.get('SYSTEM_SHUTDOWN')) {
    node.status({fill:'red',shape:'ring',text:'SHUTDOWN'});
    return null;
}
const base = (global.get('LEADS_URL') || env.get('LEADS_PUBLIC_URL') || env.get('DASHBOARD_PUBLIC_URL') || 'https://leads.shamrockbailbonds.biz').replace(/\/$/, '');
msg.url = base + '/api/automation/bond-lifecycle';
const apiKey = global.get('GAS_API_KEY') || env.get('GAS_API_KEY') || '';
msg.headers = {
    'Content-Type': 'application/json',
    'X-API-Key': apiKey,
    'X-Api-Key': apiKey
};
msg.payload = { stuck_days: 3, limit: 40 };
msg.method = 'POST';
msg._bl = { startedAt: new Date().toISOString() };
node.status({fill:'blue',shape:'dot',text:'Lifecycle sweep…'});
return msg;

msg._bl = msg._bl || {};
msg._bl.lifecycle = msg.payload;
const gasUrl = (global.get('GAS_URL') || env.get('GAS_WEBHOOK_URL') || '').split('?')[0];
if (!gasUrl) {
    node.warn('No GAS_URL — skipping closer');
    return [null, msg];
}
msg.url = gasUrl + '?action=runTheCloser';
msg.headers = { 'Content-Type': 'application/json' };
const apiKey = global.get('GAS_API_KEY') || env.get('GAS_API_KEY') || '';
if (apiKey) {
    msg.headers['X-API-Key'] = apiKey;
    msg.headers['X-Api-Key'] = apiKey;
}
msg.payload = {
    apiKey: apiKey,
    action: 'runTheCloser',
    source: 'node-red-bond-lifecycle',
    hoursBack: 72,
    maxPerRun: 15
};
msg.method = 'POST';
return [msg, null];

const life = (msg._bl && msg._bl.lifecycle) || msg.payload || {};
const c = life.counts || {};
const issues = life.issues || [];
const stuck = life.pipeline_stuck || [];
if ((c.issues || 0) === 0 && (c.pipeline_stuck || 0) === 0) {
    node.status({fill:'green',shape:'ring',text:'Lifecycle healthy'});
    return null;
}
const issueLines = issues.slice(0, 6).map(i =>
    `• ${i.defendant || i.booking_number || '?'} [${(i.flags||[]).join(', ')}] stage=${i.stage||'?'}`
).join('\n') || '_None_';
const stuckLines = stuck.slice(0, 5).map(s =>
    `• ${s.defendant || s.booking_number} @ ${s.stage}`
).join('\n') || '_None_';
msg.headers = {
    Authorization: 'Bearer ' + (global.get('SLACK_TOKEN') || env.get('SLACK_BOT_TOKEN') || ''),
    'Content-Type': 'application/json; charset=utf-8'
};
msg.payload = {
    channel: global.get('SLACK_CHANNEL_BONDS') || '#bonds',
    text: [
        '☘️ *Bond Lifecycle Manager*',
        `Active scanned: ${c.active_bonds_scanned || 0} · Issues: ${c.issues || 0} · Pipeline stuck: ${c.pipeline_stuck || 0}`,
        '',
        '*Bond issues*',
        issueLines,
        '',
        '*Pipeline stuck >3d*',
        stuckLines
    ].join('\n')
};
node.status({fill:'yellow',shape:'dot',text:`${c.issues||0} issues`});
return msg;

const err = msg.error || {};
msg.headers = {
    Authorization: 'Bearer ' + (global.get('SLACK_TOKEN') || env.get('SLACK_BOT_TOKEN') || ''),
    'Content-Type': 'application/json; charset=utf-8'
};
msg.payload = {
    channel: '#alerts',
    text: '🚨 *Bond Lifecycle Manager error*: ' + (err.message || JSON.stringify(err).slice(0, 300))
};
return msg;

if (global.get('SYSTEM_SHUTDOWN')) {
    node.status({fill:'red',shape:'ring',text:'SHUTDOWN'});
    return null;
}
const gasUrl = (global.get('GAS_URL') || env.get('GAS_WEBHOOK_URL') || '').split('?')[0];
if (!gasUrl) {
    node.error('GAS_URL not configured');
    return null;
}
msg._rm = { gasUrl, startedAt: new Date().toISOString() };
msg.url = gasUrl + '?action=runRiskIntelligenceLoop';
msg.headers = { 'Content-Type': 'application/json' };
const apiKey = global.get('GAS_API_KEY') || env.get('GAS_API_KEY') || '';
if (apiKey) {
    msg.headers['X-API-Key'] = apiKey;
    msg.headers['X-Api-Key'] = apiKey;
}
msg.payload = { apiKey: apiKey, action: 'runRiskIntelligenceLoop', source: 'node-red-risk-mitigation' };
msg.method = 'POST';
global.set('last_run_runRiskIntelligenceLoop', msg._rm.startedAt);
node.status({fill:'blue',shape:'dot',text:'Risk intelligence…'});
return msg;

msg._rm = msg._rm || {};
msg._rm.riskLoop = msg.payload;
const gasUrl = msg._rm.gasUrl;
msg.url = gasUrl + '?action=checkCourtDateProximity';
msg.headers = { 'Content-Type': 'application/json' };
const apiKey = global.get('GAS_API_KEY') || env.get('GAS_API_KEY') || '';
if (apiKey) {
    msg.headers['X-API-Key'] = apiKey;
    msg.headers['X-Api-Key'] = apiKey;
}
msg.payload = { apiKey: apiKey, action: 'checkCourtDateProximity', source: 'node-red-risk-mitigation' };
msg.method = 'POST';
return msg;

msg._rm = msg._rm || {};
msg._rm.court = msg.payload;
const gasUrl = msg._rm.gasUrl;
msg.url = gasUrl + '?action=sendAutomatedCheckIns';
msg.headers = { 'Content-Type': 'application/json' };
const apiKey = global.get('GAS_API_KEY') || env.get('GAS_API_KEY') || '';
if (apiKey) {
    msg.headers['X-API-Key'] = apiKey;
    msg.headers['X-Api-Key'] = apiKey;
}
msg.payload = { apiKey: apiKey, action: 'sendAutomatedCheckIns', source: 'node-red-risk-mitigation' };
msg.method = 'POST';
return msg;

msg._rm = msg._rm || {};
msg._rm.checkins = msg.payload;
const base = (global.get('LEADS_URL') || env.get('LEADS_PUBLIC_URL') || env.get('DASHBOARD_PUBLIC_URL') || 'https://leads.shamrockbailbonds.biz').replace(/\/$/, '');
msg.url = base + '/api/automation/risk-mitigation';
const apiKey = global.get('GAS_API_KEY') || env.get('GAS_API_KEY') || '';
msg.headers = {
    'Content-Type': 'application/json',
    'X-API-Key': apiKey,
    'X-Api-Key': apiKey
};
msg.payload = {
    high_risk_threshold: 70,
    court_hours: 48,
    limit: 40
};
msg.method = 'POST';
return msg;

const data = msg.payload || {};
const c = data.counts || {};
const actions = data.recommended_actions || [];
const fort = data.forfeiture || [];
const high = data.high_risk || [];
const urgent = (c.forfeiture || 0) > 0 || (c.high_risk || 0) > 0;
if (!urgent && (c.court_soon || 0) === 0 && (c.missed_checkins || 0) === 0) {
    node.status({fill:'green',shape:'ring',text:'Risk quiet'});
    return null;
}
const fortLines = fort.slice(0, 5).map(f =>
    `• ⚠️ ${f.name || f.booking_number} — ${f.status}`
).join('\n') || '_None_';
const highLines = high.slice(0, 5).map(h =>
    `• 🔴 ${h.name || h.booking_number} risk=${h.risk_score}`
).join('\n') || '_None_';
msg.headers = {
    Authorization: 'Bearer ' + (global.get('SLACK_TOKEN') || env.get('SLACK_BOT_TOKEN') || ''),
    'Content-Type': 'application/json; charset=utf-8'
};
msg.payload = {
    channel: (c.forfeiture || 0) > 0 ? '#alerts' : (global.get('SLACK_CHANNEL_ALERTS') || '#alerts'),
    text: [
        '🛡 *Risk Mitigation Loop*',
        `High risk: ${c.high_risk || 0} · Court 48h: ${c.court_soon || 0} · Forfeiture: ${c.forfeiture || 0} · Missed check-ins: ${c.missed_checkins || 0}`,
        '',
        '*Recommended*',
        (actions.map(a => '• ' + a).join('\n') || '_None_'),
        '',
        '*Forfeiture / FTA*',
        fortLines,
        '',
        '*High flight risk*',
        highLines
    ].join('\n')
};
node.status({fill: urgent ? 'red' : 'yellow', shape:'dot', text: urgent ? 'URGENT risk' : 'Monitor'});
return msg;

const err = msg.error || {};
msg.headers = {
    Authorization: 'Bearer ' + (global.get('SLACK_TOKEN') || env.get('SLACK_BOT_TOKEN') || ''),
    'Content-Type': 'application/json; charset=utf-8'
};
msg.payload = {
    channel: '#alerts',
    text: '🚨 *Risk Mitigation Loop error*: ' + (err.message || JSON.stringify(err).slice(0, 300))
};
return msg;
